// C# rendering helpers for the csharp-server target (spec 0002 LIB-9, LIB-11, spec 0014 GNR-6, GNR-8).
import { GeneratorError } from "../../contract.ts";
import { headerLine, type Provenance } from "../../output.ts";
import type { CSharpType } from "./types.ts";

/**
 * The first lines of every generated C# file (GNR-8, LIB-11). A file marked `<auto-generated/>` starts with nullable
 * annotations off, so the header turns them back on: LIB-11 wants generated code nullable clean.
 */
export function fileHeader(source: Provenance): string {
  return `// <auto-generated/>\n// ${headerLine(source)}\n#nullable enable\n`;
}

/** A file's header, usings, and file scoped namespace. */
export function filePrelude(
  source: Provenance,
  usings: Iterable<string>,
  namespace: string,
): string {
  const sorted = [...new Set(usings)].toSorted(compareUsings);
  let text = fileHeader(source);
  // dotnet_separate_import_directive_groups: a blank line wherever the first namespace segment changes.
  let group = "";
  for (const name of sorted) {
    const first = name.split(".")[0] ?? name;
    text += `${first === group ? "" : "\n"}using ${name};\n`;
    group = first;
  }
  return `${text}\nnamespace ${namespace};\n`;
}

/** 0 for a `System` namespace, which sorts first (dotnet_sort_system_directives_first). */
function systemRank(name: string): number {
  return name === "System" || name.startsWith("System.") ? 0 : 1;
}

/** `System` namespaces first, then the rest, each by name. */
function compareUsings(a: string, b: string): number {
  return systemRank(a) - systemRank(b) || (a < b ? -1 : a > b ? 1 : 0);
}

/** Text safe inside an XML doc comment, with `code` spans as `<c>`. */
function xmlText(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/`([^`]+)`/g, "<c>$1</c>");
}

/** One XML doc element (`summary`, `remarks`, `returns`, ...), wrapped to stay readable. */
export function docElement(tag: string, text: string, indent: string, attributes = ""): string {
  const paragraphs = text
    .replace(/\r\n?/g, "\n")
    .split(/\n\s*\n/)
    .map((paragraph) => paragraph.replace(/\s*\n\s*/g, " ").trim())
    .filter((paragraph) => paragraph !== "");
  if (paragraphs.length === 0) return "";
  const open = `<${tag}${attributes}>`;
  const close = `</${tag}>`;
  const width = 120 - indent.length - 4;
  if (paragraphs.length === 1) {
    const only = xmlText(paragraphs[0] ?? "");
    if (open.length + only.length + close.length <= width)
      return `${indent}/// ${open}${only}${close}\n`;
  }
  const lines: string[] = [open];
  paragraphs.forEach((paragraph, index) => {
    const wrapped = wrap(xmlText(paragraph), width);
    if (paragraphs.length === 1) lines.push(...wrapped);
    else {
      if (index > 0) lines.push("<para>");
      lines.push(...wrapped);
      if (index > 0) lines.push("</para>");
    }
  });
  lines.push(close);
  return lines.map((line) => `${indent}/// ${line}\n`).join("");
}

/** A summary, and remarks when there is more to say. */
export function docComment(summary: string, remarks: string, indent: string): string {
  return docElement("summary", summary, indent) + docElement("remarks", remarks, indent);
}

/** Splits a line at spaces so each part fits `width` (dotnet format leaves comments as they are). */
function wrap(line: string, width: number): string[] {
  const parts: string[] = [];
  let current = "";
  for (const word of line.split(" ")) {
    if (current !== "" && current.length + 1 + word.length > width) {
      parts.push(current);
      current = word;
    } else {
      current = current === "" ? word : `${current} ${word}`;
    }
  }
  parts.push(current);
  return parts;
}

/** A C# string literal. */
export function csString(value: string): string {
  let text = "";
  for (const char of value) {
    const code = char.codePointAt(0) ?? 0;
    if (char === "\\") text += "\\\\";
    else if (char === '"') text += '\\"';
    else if (char === "\n") text += "\\n";
    else if (char === "\r") text += "\\r";
    else if (char === "\t") text += "\\t";
    else if (code < 0x20 || code === 0x7f) text += `\\u${code.toString(16).padStart(4, "0")}`;
    else text += char;
  }
  return `"${text}"`;
}

// https://learn.microsoft.com/dotnet/csharp/language-reference/keywords: the reserved keywords, which a parameter
// may only take with an `@` in front.
const keywords: ReadonlySet<string> = new Set([
  "abstract",
  "as",
  "base",
  "bool",
  "break",
  "byte",
  "case",
  "catch",
  "char",
  "checked",
  "class",
  "const",
  "continue",
  "decimal",
  "default",
  "delegate",
  "do",
  "double",
  "else",
  "enum",
  "event",
  "explicit",
  "extern",
  "false",
  "finally",
  "fixed",
  "float",
  "for",
  "foreach",
  "goto",
  "if",
  "implicit",
  "in",
  "int",
  "interface",
  "internal",
  "is",
  "lock",
  "long",
  "namespace",
  "new",
  "null",
  "object",
  "operator",
  "out",
  "override",
  "params",
  "private",
  "protected",
  "public",
  "readonly",
  "ref",
  "return",
  "sbyte",
  "sealed",
  "short",
  "sizeof",
  "stackalloc",
  "static",
  "string",
  "struct",
  "switch",
  "this",
  "throw",
  "true",
  "try",
  "typeof",
  "uint",
  "ulong",
  "unchecked",
  "unsafe",
  "ushort",
  "using",
  "virtual",
  "void",
  "volatile",
  "while",
]);

/** A parameter name for a camelCase contract name, with `@` when it is a keyword. */
export function parameterName(name: string, where: string): string {
  if (!/^[a-z][A-Za-z0-9]*$/.test(name))
    throw new GeneratorError(`${where}: ${name} can't be a C# parameter name.`);
  return keywords.has(name) ? `@${name}` : name;
}

export function csTypeName(type: CSharpType): string {
  switch (type.kind) {
    case "string":
      return "string";
    case "int":
      return "int";
    case "long":
      return "long";
    case "double":
      return "double";
    case "bool":
      return "bool";
    case "guid":
      return "Guid";
    case "dateTimeOffset":
      return "DateTimeOffset";
    case "any":
      return "JsonElement?";
    case "enum":
    case "class":
      return type.name;
    case "list":
      return `IReadOnlyList<${csTypeName(type.items)}>`;
    case "map":
      return `IReadOnlyDictionary<string, ${csTypeName(type.values)}>`;
    case "nullable":
      return `${csTypeName(type.inner)}?`;
  }
}

/** The non nullable form of a type. */
export function nonNull(type: CSharpType): CSharpType {
  return type.kind === "nullable" ? type.inner : type;
}

/** True when a value of the type may be null. */
export function isNullable(type: CSharpType): boolean {
  return type.kind === "nullable" || type.kind === "any";
}

/** The nullable form of a type. */
export function nullable(type: CSharpType): CSharpType {
  return isNullable(type) ? type : { kind: "nullable", inner: type };
}

/** True for a C# reference type, which needs a null check rather than a default. */
export function isReference(type: CSharpType): boolean {
  return ["string", "class", "list", "map"].includes(nonNull(type).kind);
}
